/* Symbol versions for the shim's interposers, so Live's versioned references
   bind to them instead of the libraries' copies:
   QWidget::resize (window.cpp), QWidget::update(QRect) (glsurface.cpp), QDrag::exec (dragcursor.cpp), snd_seq_event_input (alsamidi.cpp),
   snd_pcm_open, snd_pcm_hw_params_set_format_mask, snd_pcm_hw_params_set_channels
   and snd_pcm_hw_params_set_buffer_size (alsaaudio.cpp), the card scan
   functions, stat and stat64 (pwdevices.cpp), execv, execve, system, posix_spawn and posix_spawnp (standalone.cpp). */
Qt_5 {
    global: _ZN7QWidget6resizeERK5QSize; _ZN7QWidget6updateERK5QRect; _ZN5QDrag4execE6QFlagsIN2Qt10DropActionEE;
};
ALSA_0.9 {
    global: snd_seq_event_input; snd_pcm_open; snd_pcm_hw_params_set_format_mask; snd_pcm_hw_params_set_channels;
        snd_pcm_hw_params_set_buffer_size;
        snd_card_next; snd_ctl_open; snd_ctl_close; snd_ctl_card_info; snd_ctl_card_info_get_name;
        snd_ctl_pcm_next_device; snd_ctl_pcm_info; snd_pcm_info_get_name;
};
GLIBC_2.33 {
    global: stat; stat64;
};
GLIBC_2.2.5 {
    global: execv; execve; system;
};
GLIBC_2.15 {
    global: posix_spawn; posix_spawnp;
};
